/**
 * Shared fetch signature used by the Nova AI TypeScript SDK.
 *
 * Provide this when you want to inject a custom `fetch` implementation for
 * testing, retries, logging, or older Node.js runtimes.
 */
export type NovaAIFetch = (input: string, init?: RequestInit) => Promise<Response>;

/**
 * Basic list response used by Nova AI collection endpoints.
 */
export type APIListResponse<T> = {
    object: 'list';
    data: T[];
    first_id?: string;
    last_id?: string;
    has_more?: boolean;
};

/**
 * Shape used by Nova AI object responses.
 */
export type APIObject<T extends string, E extends Record<string, unknown> = {}> = {
    id: string;
    object: T;
} & E;

/**
 * Provider field definitions exposed by the API.
 */
export type ProviderSchemaField = {
    readonly name: string;
    label: string;
    readonly type: 'string' | 'number' | 'boolean' | 'null' | 'object' | 'secret';
    description?: string;
    default?: string | number | boolean | null | Record<string, unknown> | unknown[];
    required?: boolean;
};

/**
 * Runtime provider metadata.
 */
export type ProviderResponse = APIObject<'provider', {
    name: string;
    description?: string;
    styling?: Record<string, unknown>;
    readonly schema?: ProviderSchemaField[];
}>;

/**
 * Runtime model metadata.
 */
export type ModelResponse = APIObject<'model', {
    created: number;
    owned_by: string;
    enabled?: boolean;
    name?: string | null;
    description?: string | null;
    family?: string | null;
    variant?: string | null;
    aliases?: string[];
    tags?: string[];
    capabilities?: string[];
    context_window?: number | null;
    max_model_len?: number | null;
    max_output_tokens?: number | null;
    input_cost_per_1m?: number | null;
    output_cost_per_1m?: number | null;
    currency?: string | null;
    [key: string]: unknown;
}>;

/**
 * Supported chat message roles.
 */
export type ChatRole = 'system' | 'user' | 'assistant' | 'tool';

/**
 * A chat message sent to or returned from the API.
 */
export type ChatMessage = {
    role: ChatRole;
    content: unknown;
    [key: string]: unknown;
};

/**
 * Token usage details returned by OpenAI-compatible responses.
 */
export type ChatCompletionTokenDetails = {
    cached_tokens?: number;
    reasoning_tokens?: number;
    accepted_prediction_tokens?: number;
    rejected_prediction_tokens?: number;
    [key: string]: unknown;
};

/**
 * Usage information returned by chat completions.
 */
export type ChatCompletionUsage = {
    prompt_tokens?: number;
    completion_tokens?: number;
    total_tokens?: number;
    prompt_tokens_details?: ChatCompletionTokenDetails;
    completion_tokens_details?: ChatCompletionTokenDetails;
    [key: string]: unknown;
};

export type ChatCompletionUsageSource = 'provider' | 'gateway_estimated';

/**
 * Gateway-standard chat telemetry returned on chat completions and chunks.
 */
export type ChatCompletionMetrics = {
    source?: string;
    completion_tokens?: number;
    total_duration_ms?: number;
    tokens_per_second?: number;
    [key: string]: unknown;
};

/**
 * A single chat completion choice.
 */
export type ChatCompletionChoice = {
    index: number;
    message: ChatMessage & {refusal?: string | null};
    finish_reason: string | null;
    [key: string]: unknown;
};

/**
 * Non-streaming chat completion response.
 */
export type ChatCompletionResponse = {
    id: string;
    object: 'chat.completion' | string;
    created: number;
    model: string;
    choices: ChatCompletionChoice[];
    usage?: ChatCompletionUsage;
    usage_source?: ChatCompletionUsageSource;
    metrics?: ChatCompletionMetrics;
    [key: string]: unknown;
};

/**
 * Streaming delta payload for chat completions.
 */
export type ChatCompletionChunkChoice = {
    index: number;
    delta: Partial<ChatMessage> & {refusal?: string | null};
    finish_reason?: string | null;
    [key: string]: unknown;
};

/**
 * One server-sent chat completion chunk.
 */
export type ChatCompletionChunk = {
    id?: string;
    object: 'chat.completion.chunk' | string;
    created?: number;
    model?: string;
    choices?: ChatCompletionChunkChoice[];
    usage?: ChatCompletionUsage;
    usage_source?: ChatCompletionUsageSource;
    metrics?: ChatCompletionMetrics;
    [key: string]: unknown;
};

/**
 * Chat completion request body accepted by the public API.
 */
export type ChatCompletionRequest = {
    model: string;
    messages: ChatMessage[];
    stream?: boolean;
    max_tokens?: number;
    max_completion_tokens?: number;
    temperature?: number;
    [key: string]: unknown;
};

/**
 * Input accepted by the embeddings endpoint.
 */
export type EmbeddingRequestInput = string | string[];

/**
 * Embedding request body accepted by the public API.
 */
export type EmbeddingRequest = {
    model: string;
    input: EmbeddingRequestInput;
    encoding_format?: 'float' | string;
    dimensions?: number;
    user?: string;
    [key: string]: unknown;
};

/**
 * Individual embedding row.
 */
export type EmbeddingData = {
    object: 'embedding' | string;
    index: number;
    embedding: number[];
    [key: string]: unknown;
};

/**
 * Embedding token usage.
 */
export type EmbeddingUsage = {
    prompt_tokens: number;
    total_tokens: number;
    [key: string]: unknown;
};

/**
 * Embedding response from the public API.
 */
export type EmbeddingResponse = {
    object: 'list' | string;
    data: EmbeddingData[];
    model: string;
    usage?: EmbeddingUsage;
    [key: string]: unknown;
};

/**
 * Image generation request body accepted by the public API.
 */
export type ImageGenerationRequest = {
    model: string;
    prompt: string;
    n?: number;
    size?: string;
    quality?: string;
    response_format?: 'url' | 'b64_json';
    style?: string;
    user?: string;
    [key: string]: unknown;
};

/**
 * Individual generated image payload.
 */
export type ImageGenerationData = {
    url?: string;
    b64_json?: string;
    revised_prompt?: string;
    [key: string]: unknown;
};

/**
 * Image generation response from the public API.
 */
export type ImageGenerationResponse = {
    created: number;
    data: ImageGenerationData[];
    [key: string]: unknown;
};

/**
 * File-like object accepted by audio upload endpoints.
 */
export type AudioUpload = File | Blob;

/**
 * Audio transcription request body accepted by the public API.
 */
export type AudioTranscriptionRequest = {
    model: string;
    file: AudioUpload;
    filename?: string;
    language?: string;
    prompt?: string;
    response_format?: 'json' | 'text' | 'srt' | 'verbose_json' | 'vtt';
    temperature?: number;
    [key: string]: unknown;
};

/**
 * Audio translation request body accepted by the public API.
 */
export type AudioTranslationRequest = {
    model: string;
    file: AudioUpload;
    filename?: string;
    prompt?: string;
    response_format?: 'json' | 'text' | 'srt' | 'verbose_json' | 'vtt';
    temperature?: number;
    [key: string]: unknown;
};

/**
 * Shared response returned by transcription and translation endpoints.
 */
export type AudioTextResponse = {
    text: string;
    [key: string]: unknown;
};

/**
 * Speech synthesis request body accepted by the public API.
 */
export type SpeechRequest = {
    model: string;
    input: string;
    voice?: string;
    language?: string;
    instructions?: string;
    response_format?: 'mp3' | 'opus' | 'aac' | 'flac' | 'wav' | 'pcm';
    speed?: number;
    task_type?: string;
    ref_audio?: string;
    ref_text?: string;
    max_new_tokens?: number;
    [key: string]: unknown;
};

/**
 * Available preset voices for the selected speech provider/model.
 */
export type VoiceListResponse = {
    voices?: string[];
    [key: string]: unknown;
};

/**
 * OpenAI-style error details returned by the runtime API.
 */
export type NovaAIErrorBody = {
    error?: {
        message?: string;
        type?: string | null;
        param?: string | null;
        code?: string | null;
    };
    message?: string;
    [key: string]: unknown;
};

/**
 * Per-request options shared by runtime methods.
 */
export type NovaAIRequestOptions = {
    configId?: string;
    requestId?: string;
    signal?: AbortSignal;
    headers?: HeadersInit;
};

/**
 * Chat streaming options. Identical to regular request options.
 */
export type NovaAIChatStreamOptions = NovaAIRequestOptions;

/**
 * Client configuration for the Node SDK.
 */
export type NovaAIOptions = {
    baseUrl?: string;
    apiKey: string;
    fetch?: NovaAIFetch;
    headers?: HeadersInit;
};

/**
 * Parsed event yielded from a streaming chat request.
 *
 * Most applications only need the `chunk` events. The final `done` event is
 * emitted when the server sends the `[DONE]` sentinel.
 */
export type ChatStreamEvent =
    | {type: 'chunk'; data: ChatCompletionChunk}
    | {type: 'done'};

/**
 * Error thrown when the runtime API returns a non-2xx response.
 */
export class NovaAIError extends Error {
    readonly status: number;
    readonly body: unknown;
    readonly response: Response;
    readonly requestId: string | null;
    readonly configId: string | null;
    readonly type: string | null;
    readonly code: string | null;

    constructor(message: string, options: {
        status: number;
        body: unknown;
        response: Response;
        requestId: string | null;
        configId: string | null;
        type: string | null;
        code: string | null;
    }) {
        super(message);
        this.name = 'NovaAIError';
        this.status = options.status;
        this.body = options.body;
        this.response = options.response;
        this.requestId = options.requestId;
        this.configId = options.configId;
        this.type = options.type;
        this.code = options.code;
    }
}

const defaultFetch: NovaAIFetch = (input, init) => fetch(input, init);
const defaultBaseUrl = 'https://api.nova.datalabrotterdam.nl/v1';

const normalizeBaseUrl = (baseUrl: string) => {
    const trimmed = baseUrl.replace(/\/+$/, '');
    return trimmed.endsWith('/v1') ? trimmed : `${trimmed}/v1`;
};

const toQueryString = (params: Record<string, string | number | undefined>) => {
    const search = new URLSearchParams();
    for (const [key, value] of Object.entries(params)) {
        if (value !== undefined)
            search.set(key, String(value));
    }

    const query = search.toString();
    return query ? `?${query}` : '';
};

const tryParseJson = (text: string): unknown => {
    try {
        return JSON.parse(text) as unknown;
    } catch {
        return text;
    }
};

const getErrorMessage = (body: unknown, fallbackStatus: number) => {
    if (body && typeof body === 'object') {
        const record = body as NovaAIErrorBody;
        if (typeof record.error?.message === 'string' && record.error.message)
            return record.error.message;
        if (typeof record.message === 'string' && record.message)
            return record.message;
    }

    return `Nova AI request failed with ${fallbackStatus}`;
};

const getErrorType = (body: unknown) => {
    if (body && typeof body === 'object') {
        const record = body as NovaAIErrorBody;
        return typeof record.error?.type === 'string' ? record.error.type : null;
    }

    return null;
};

const getErrorCode = (body: unknown) => {
    if (body && typeof body === 'object') {
        const record = body as NovaAIErrorBody;
        return typeof record.error?.code === 'string' ? record.error.code : null;
    }

    return null;
};

const isFormData = (value: unknown): value is FormData => (
    typeof FormData !== 'undefined' && value instanceof FormData
);

const shouldSetJsonContentType = (body: BodyInit | null | undefined) => (
    typeof body === 'string'
);

const createAudioFormData = (
    input: AudioTranscriptionRequest | AudioTranslationRequest
) => {
    const formData = new FormData();
    const {file, filename, ...rest} = input;
    const inferredName =
        filename
        ?? ('name' in file && typeof file.name === 'string' && file.name ? file.name : 'audio');

    formData.append('file', file, inferredName);
    for (const [key, value] of Object.entries(rest)) {
        if (value === undefined || value === null)
            continue;
        formData.append(key, String(value));
    }
    return formData;
};

/**
 * Converts a raw server-sent-events HTTP response into typed chat events.
 */
const createEventStream = async function* (response: Response): AsyncGenerator<ChatStreamEvent> {
    if (!response.body)
        throw new Error('Streaming response body is missing');

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';

    while (true) {
        const {done, value} = await reader.read();
        buffer += decoder.decode(value ?? new Uint8Array(), {stream: !done});

        let boundaryIndex = buffer.indexOf('\n\n');
        while (boundaryIndex !== -1) {
            const block = buffer.slice(0, boundaryIndex);
            buffer = buffer.slice(boundaryIndex + 2);

            const dataLines = block
                .split('\n')
                .map((line) => line.replace(/\r$/, ''))
                .filter((line) => line.startsWith('data:'))
                .map((line) => line.slice(5).trimStart());

            if (dataLines.length > 0) {
                const payload = dataLines.join('\n');
                if (payload === '[DONE]') {
                    yield {type: 'done'};
                    return;
                }

                yield {
                    type: 'chunk',
                    data: JSON.parse(payload) as ChatCompletionChunk
                };
            }

            boundaryIndex = buffer.indexOf('\n\n');
        }

        if (done) {
            const trimmed = buffer.trim();
            if (trimmed) {
                const dataLines = trimmed
                    .split('\n')
                    .filter((line) => line.startsWith('data:'))
                    .map((line) => line.slice(5).trimStart());

                if (dataLines.length > 0) {
                    const payload = dataLines.join('\n');
                    if (payload === '[DONE]') {
                        yield {type: 'done'};
                    } else {
                        yield {
                            type: 'chunk',
                            data: JSON.parse(payload) as ChatCompletionChunk
                        };
                    }
                }
            }
            return;
        }
    }
};

/**
 * Collects the plain-text assistant response from a chat stream.
 *
 * This helper is useful when you want the convenience of streaming on the wire
 * but only need the final combined text in your application code.
 *
 * @example
 * ```ts
 * const text = await collectChatText(client.chat.completions.stream({
 *   model: "llama3.2",
 *   messages: [{role: "user", content: "Say hello"}]
 * }));
 * ```
 */
export const collectChatText = async (stream: AsyncIterable<ChatStreamEvent>): Promise<string> => {
    let text = '';
    for await (const event of stream) {
        if (event.type !== 'chunk')
            continue;

        const content = event.data.choices?.[0]?.delta?.content;
        if (typeof content === 'string')
            text += content;
    }
    return text;
};

/**
 * Beginner-friendly client for the public Nova AI runtime API.
 *
 * The client intentionally mirrors a small subset of the OpenAI-style runtime
 * surface:
 *
 * - `providers.list()` for provider discovery
 * - `models.list()` for model discovery
 * - `chat.completions.create()` for non-streaming chat
 * - `chat.completions.stream()` for streaming chat
 * - `embeddings.create()` for vector embeddings
 * - `images.generations.create()` for image generation
 * - `audio.transcriptions.create()` for audio transcription
 * - `audio.translations.create()` for audio translation
 * - `audio.speech.create()` for text-to-speech
 *
 * @example
 * ```ts
 * const client = new NovaAI({
 *   baseUrl: "http://localhost:3000",
 *   apiKey: process.env.NOVA_API_KEY!
 * });
 * ```
 */
export class NovaAI {
    readonly baseUrl: string;
    readonly apiKey: string;
    readonly fetch: NovaAIFetch;
    readonly headers?: HeadersInit;

    /**
     * Provider discovery methods.
     */
    public readonly providers = {
        /**
         * Lists all registered providers exposed by the API.
         */
        list: (): Promise<APIListResponse<ProviderResponse>> => this.request('/providers')
    };

    /**
     * Runtime model discovery methods.
     */
    public readonly models = {
        /**
         * Lists models available to the current runtime key.
         *
         * Use `limit` and `after` for simple cursor-based pagination.
         */
        list: (options: {limit?: number; after?: string} = {}): Promise<APIListResponse<ModelResponse>> => (
            this.request(`/models${toQueryString(options)}`)
        )
    };

    /**
     * Chat completion methods.
     */
    public readonly chat = {
        completions: {
            /**
             * Creates a standard, non-streaming chat completion.
             *
             * @param request Chat completion payload in the OpenAI-compatible shape.
             * @param options Optional request metadata such as `configId` or `requestId`.
             */
            create: (
                request: ChatCompletionRequest,
                options?: NovaAIRequestOptions
            ): Promise<ChatCompletionResponse> => (
                this.request('/chat/completions', {
                    method: 'POST',
                    body: JSON.stringify(request)
                }, options)
            ),

            /**
             * Creates a streaming chat completion and returns parsed SSE events.
             *
             * The returned value is an async iterable, so you can consume it
             * directly with `for await ... of` without awaiting `stream()`
             * first.
             *
             * @example
             * ```ts
             * for await (const event of client.chat.completions.stream({
             *   model: "llama3.2",
             *   messages: [{role: "user", content: "Write a haiku"}]
             * })) {
             *   if (event.type === "chunk") {
             *     process.stdout.write(event.data.choices?.[0]?.delta?.content ?? "");
             *   }
             * }
             * ```
             */
            stream: (
                request: ChatCompletionRequest,
                options?: NovaAIChatStreamOptions
            ): AsyncIterable<ChatStreamEvent> => this.streamChatCompletion(request, options)
        }
    };

    /**
     * Embeddings methods.
     */
    public readonly embeddings = {
        /**
         * Creates embeddings for one string or multiple strings.
         *
         * Pass a single string for the simplest case, or an array of strings to
         * embed multiple inputs in one request.
         */
        create: (
            request: EmbeddingRequest,
            options?: NovaAIRequestOptions
        ): Promise<EmbeddingResponse> => (
            this.request('/embeddings', {
                method: 'POST',
                body: JSON.stringify(request)
            }, options)
        )
    };

    /**
     * Image generation methods.
     */
    public readonly images = {
        generations: {
            /**
             * Generates one or more images from a text prompt.
             */
            create: (
                request: ImageGenerationRequest,
                options?: NovaAIRequestOptions
            ): Promise<ImageGenerationResponse> => (
                this.request('/images/generations', {
                    method: 'POST',
                    body: JSON.stringify(request)
                }, options)
            )
        }
    };

    /**
     * Audio methods.
     */
    public readonly audio = {
        transcriptions: {
            /**
             * Transcribes an audio file using the OpenAI-compatible runtime API.
             */
            create: (
                request: AudioTranscriptionRequest,
                options?: NovaAIRequestOptions
            ): Promise<AudioTextResponse> => (
                this.request('/audio/transcriptions', {
                    method: 'POST',
                    body: createAudioFormData(request)
                }, options)
            )
        },
        translations: {
            /**
             * Translates an audio file to English using the OpenAI-compatible runtime API.
             */
            create: (
                request: AudioTranslationRequest,
                options?: NovaAIRequestOptions
            ): Promise<AudioTextResponse> => (
                this.request('/audio/translations', {
                    method: 'POST',
                    body: createAudioFormData(request)
                }, options)
            )
        },
        speech: {
            /**
             * Generates a speech audio file and returns it as a `Blob`.
             */
            create: (
                request: SpeechRequest,
                options?: NovaAIRequestOptions
            ): Promise<Blob> => (
                this.requestBlob('/audio/speech', {
                    method: 'POST',
                    body: JSON.stringify(request)
                }, options)
            )
        },
        voices: {
            /**
             * Lists non-uploaded voices exposed by the selected speech provider/model.
             */
            list: (
                options?: NovaAIRequestOptions
            ): Promise<VoiceListResponse> => (
                this.request('/audio/voices', undefined, options)
            )
        }
    };

    /**
     * Creates a new Nova AI client instance.
     *
     * @param options.baseUrl Base URL of the Nova AI API. Defaults to `https://api.nova.datalabrotterdam.nl/v1`.
     * @param options.apiKey Runtime API key used for bearer authentication.
     * @param options.fetch Optional custom fetch implementation.
     * @param options.headers Optional headers that should be sent with every request.
     */
    constructor(options: NovaAIOptions) {
        this.baseUrl = normalizeBaseUrl(options.baseUrl ?? defaultBaseUrl);
        this.apiKey = options.apiKey;
        this.fetch = options.fetch ?? defaultFetch;
        this.headers = options.headers;
    }

    private async request<T>(path: string, init: RequestInit = {}, options?: NovaAIRequestOptions): Promise<T> {
        const response = await this.rawRequest(path, init, options);
        const text = await response.text();
        return (text ? tryParseJson(text) : null) as T;
    }

    private async requestBlob(path: string, init: RequestInit = {}, options?: NovaAIRequestOptions): Promise<Blob> {
        const response = await this.rawRequest(path, init, options);
        return response.blob();
    }

    private async *streamChatCompletion(
        request: ChatCompletionRequest,
        options?: NovaAIChatStreamOptions
    ): AsyncGenerator<ChatStreamEvent> {
        const response = await this.rawRequest('/chat/completions', {
            method: 'POST',
            body: JSON.stringify({
                ...request,
                stream: true
            })
        }, {
            ...options,
            headers: {
                Accept: 'text/event-stream',
                ...options?.headers
            }
        });

        yield* createEventStream(response);
    }

    private async rawRequest(path: string, init: RequestInit = {}, options?: NovaAIRequestOptions): Promise<Response> {
        const headers = new Headers({
            Accept: 'application/json',
            Authorization: `Bearer ${this.apiKey}`
        });

        if (shouldSetJsonContentType(init.body))
            headers.set('Content-Type', 'application/json');

        mergeHeaders(headers, this.headers);
        mergeHeaders(headers, options?.headers);
        mergeHeaders(headers, init.headers);

        if (isFormData(init.body))
            headers.delete('Content-Type');

        if (options?.configId)
            headers.set('x-config-id', options.configId);

        if (options?.requestId)
            headers.set('x-request-id', options.requestId);

        const response = await this.fetch(`${this.baseUrl}${path}`, {
            ...init,
            headers,
            signal: options?.signal ?? init.signal
        });

        if (!response.ok) {
            const text = await response.text();
            const body = text ? tryParseJson(text) : null;
            throw new NovaAIError(getErrorMessage(body, response.status), {
                status: response.status,
                body,
                response,
                requestId: response.headers.get('x-request-id'),
                configId: response.headers.get('x-config-id'),
                type: getErrorType(body),
                code: getErrorCode(body)
            });
        }

        return response;
    }
}

const mergeHeaders = (target: Headers, source?: HeadersInit) => {
    if (!source) return;
    new Headers(source).forEach((value, key) => {
        target.set(key, value);
    });
};
